export const getProductImage = (productName) => {
  if (!productName) return productImages.default;
  const key = productName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
  return productImages[key] || productImages.default;
};

export default productImages;
